CREATE     PROCEDURE [synapse_fo].[usp_Insert_CUSTTRANS]
AS
/*
	Created by: Raj Maddala
	Created on: 2023-05-15 10:29:42
	Description: Insert stored procedure for CUSTTRANS from synapse finops datalake to BI
*/
BEGIN
	INSERT INTO [synapse_fo].[CUSTTRANS]
	(
		[ACCOUNTINGEVENT],
		[ACCOUNTNUM],
		[AMOUNTCUR],
		[AMOUNTMST],
		[APPROVED],
		[APPROVER],
		[BANKCENTRALBANKPURPOSECODE],
		[BANKCENTRALBANKPURPOSETEXT],
		[BANKLCEXPORTLINE],
		[BANKREMITTANCEFILEID],
		[BILLOFEXCHANGEID],
		[BILLOFEXCHANGESEQNUM],
		[BILLOFEXCHANGESTATUS],
		[CANCELLEDPAYMENT],
		[CASHDISCBASEDATE],
		[CASHDISCCODE],
		[CASHPAYMENT],
		[CLOSED],
		[COLLECTIONLETTER],
		[COLLECTIONLETTERCODE],
		[COMPANYBANKACCOUNTID],
		[CONTROLNUM],
		[CORRECT],
		[CREATEDBY],
		[CREATEDDATETIME],
		[CREATEDTRANSACTIONID],
		[CREDMANEXCLUDEFROMCREDITCONTROL],
		[CURRENCYCODE],
		[CUSTAUTOMATIONEXCLUDE],
		[CUSTAUTOMATIONPREDICTIONSENT],
		[CUSTAUTOMATIONPREDUNNINGSENT],
		[CUSTBILLINGCLASSIFICATION],
		[CUSTEXCHADJUSTMENTREALIZED],
		[CUSTEXCHADJUSTMENTUNREALIZED],
		[DATAAREAID],
		[DataLakeModified_DateTime],
		[DEFAULTDIMENSION],
		[DELIVERYMODE],
		[DIRECTDEBITMANDATE],
		[DOCUMENTDATE],
		[DOCUMENTNUM],
		[DUEDATE],
		[EUROTRIANGULATION],
		[EXCHADJUSTMENT],
		[EXCHADJUSTMENTREPORTING],
		[EXCHRATE],
		[EXCHRATESECOND],
		--[FileName],
		[FIXEDEXCHRATE],
		[INTEREST],
		[INVOICE],
		[INVOICEPROJECT],
		[INVOICETYPE_IT],
		[LASTEXCHADJ],
		[LASTEXCHADJRATE],
		[LASTEXCHADJRATEREPORTING],
		[LASTEXCHADJVOUCHER],
		[LastProcessedChange_DateTime],
		[LASTSETTLEACCOUNTNUM],
		[LASTSETTLECOMPANY],
		[LASTSETTLEDATE],
		[LASTSETTLEVOUCHER],
		--[LSN],
		[MCRPAYMORDERID],
		[MODIFIEDBY],
		[MODIFIEDDATETIME],
		[MODIFIEDTRANSACTIONID],
		[OFFSETRECID],
		[ORDERACCOUNT],
		[PARTITION],
		[PAYMID],
		[PAYMMETHOD],
		[PAYMMODE],
		[PAYMREFERENCE],
		[PAYMSCHEDID],
		[PAYMSPEC],
		[PAYMTERMID],
		[POSTINGPROFILE],
		[POSTINGPROFILECLOSE],
		[PREPAYMENT],
		[REASONREFRECID],
		[RECID],
		[RECVERSION],
		[REPORTINGCURRENCYAMOUNT],
		[REPORTINGCURRENCYCROSSRATE],
		[REPORTINGCURRENCYEXCHRATE],
		[REPORTINGCURRENCYEXCHRATESECONDARY],
		[REPORTINGEXCHADJUSTMENTREALIZED],
		[REPORTINGEXCHADJUSTMENTUNREALIZED],
		[RETAILCUSTTRANS],
		[RETAILSTOREID],
		[RETAILTERMINALID],
		[RETAILTRANSACTIONID],
		--[RICSPAYMENTSTATE],
		--[RICSPAYMENTSTATUS],
		[SETTLEAMOUNT_MX],
		[SETTLEAMOUNTCUR],
		[SETTLEAMOUNTMST],
		[SETTLEAMOUNTREPORTING],
		[SETTLEMENT],
		--[SKS_BR_DDR_ISSELECTED],
		--[SKS_DD_ISDIRECTDEBIT],
		--[SysRowId],
		[TAXINVOICESALESID],
		[THIRDPARTYBANKACCOUNTID],
		[TRANSDATE],
		[TRANSTYPE],
		[TXT],
		[VOUCHER]
	)
	SELECT 
		stg.[ACCOUNTINGEVENT],
		stg.[ACCOUNTNUM],
		stg.[AMOUNTCUR],
		stg.[AMOUNTMST],
		stg.[APPROVED],
		stg.[APPROVER],
		stg.[BANKCENTRALBANKPURPOSECODE],
		stg.[BANKCENTRALBANKPURPOSETEXT],
		stg.[BANKLCEXPORTLINE],
		stg.[BANKREMITTANCEFILEID],
		stg.[BILLOFEXCHANGEID],
		stg.[BILLOFEXCHANGESEQNUM],
		stg.[BILLOFEXCHANGESTATUS],
		stg.[CANCELLEDPAYMENT],
		stg.[CASHDISCBASEDATE],
		stg.[CASHDISCCODE],
		stg.[CASHPAYMENT],
		stg.[CLOSED],
		stg.[COLLECTIONLETTER],
		stg.[COLLECTIONLETTERCODE],
		stg.[COMPANYBANKACCOUNTID],
		stg.[CONTROLNUM],
		stg.[CORRECT],
		stg.[CREATEDBY],
		stg.[CREATEDDATETIME],
		stg.[CREATEDTRANSACTIONID],
		stg.[CREDMANEXCLUDEFROMCREDITCONTROL],
		stg.[CURRENCYCODE],
		stg.[CUSTAUTOMATIONEXCLUDE],
		stg.[CUSTAUTOMATIONPREDICTIONSENT],
		stg.[CUSTAUTOMATIONPREDUNNINGSENT],
		stg.[CUSTBILLINGCLASSIFICATION],
		stg.[CUSTEXCHADJUSTMENTREALIZED],
		stg.[CUSTEXCHADJUSTMENTUNREALIZED],
		stg.[DATAAREAID],
		stg.[DataLakeModified_DateTime],
		stg.[DEFAULTDIMENSION],
		stg.[DELIVERYMODE],
		stg.[DIRECTDEBITMANDATE],
		stg.[DOCUMENTDATE],
		stg.[DOCUMENTNUM],
		stg.[DUEDATE],
		stg.[EUROTRIANGULATION],
		stg.[EXCHADJUSTMENT],
		stg.[EXCHADJUSTMENTREPORTING],
		stg.[EXCHRATE],
		stg.[EXCHRATESECOND],
		--stg.--[FileName],
		stg.[FIXEDEXCHRATE],
		stg.[INTEREST],
		stg.[INVOICE],
		stg.[INVOICEPROJECT],
		stg.[INVOICETYPE_IT],
		stg.[LASTEXCHADJ],
		stg.[LASTEXCHADJRATE],
		stg.[LASTEXCHADJRATEREPORTING],
		stg.[LASTEXCHADJVOUCHER],
		stg.[LastProcessedChange_DateTime],
		stg.[LASTSETTLEACCOUNTNUM],
		stg.[LASTSETTLECOMPANY],
		stg.[LASTSETTLEDATE],
		stg.[LASTSETTLEVOUCHER],
		--stg.--[LSN],
		stg.[MCRPAYMORDERID],
		stg.[MODIFIEDBY],
		stg.[MODIFIEDDATETIME],
		stg.[MODIFIEDTRANSACTIONID],
		stg.[OFFSETRECID],
		stg.[ORDERACCOUNT],
		stg.[PARTITION],
		stg.[PAYMID],
		stg.[PAYMMETHOD],
		stg.[PAYMMODE],
		stg.[PAYMREFERENCE],
		stg.[PAYMSCHEDID],
		stg.[PAYMSPEC],
		stg.[PAYMTERMID],
		stg.[POSTINGPROFILE],
		stg.[POSTINGPROFILECLOSE],
		stg.[PREPAYMENT],
		stg.[REASONREFRECID],
		stg.[RECID],
		stg.[RECVERSION],
		stg.[REPORTINGCURRENCYAMOUNT],
		stg.[REPORTINGCURRENCYCROSSRATE],
		stg.[REPORTINGCURRENCYEXCHRATE],
		stg.[REPORTINGCURRENCYEXCHRATESECONDARY],
		stg.[REPORTINGEXCHADJUSTMENTREALIZED],
		stg.[REPORTINGEXCHADJUSTMENTUNREALIZED],
		stg.[RETAILCUSTTRANS],
		stg.[RETAILSTOREID],
		stg.[RETAILTERMINALID],
		stg.[RETAILTRANSACTIONID],
		--stg.[RICSPAYMENTSTATE],
		--stg.[RICSPAYMENTSTATUS],
		stg.[SETTLEAMOUNT_MX],
		stg.[SETTLEAMOUNTCUR],
		stg.[SETTLEAMOUNTMST],
		stg.[SETTLEAMOUNTREPORTING],
		stg.[SETTLEMENT],
		--stg.[SKS_BR_DDR_ISSELECTED],
		--stg.[SKS_DD_ISDIRECTDEBIT],
		--stg.--[SysRowId],
		stg.[TAXINVOICESALESID],
		stg.[THIRDPARTYBANKACCOUNTID],
		stg.[TRANSDATE],
		stg.[TRANSTYPE],
		stg.[TXT],
		stg.[VOUCHER]	
	FROM [staging_fo].[CUSTTRANS] stg
		LEFT JOIN [synapse_fo].[CUSTTRANS] tgt
			ON stg.[RECID] = tgt.[RECID] 
		
	WHERE tgt.[RECID] IS NULL
END
